package tunnel
package tunnel

import (
	"encoding/binary"
	"fmt"
	"io"
	"net"

	"golang.org/x/crypto/ssh"
	"golang.zx2c4.com/wintun"
)

// TunnelManager manages the VPN tunnel connection
type TunnelManager struct {
	adapter   *wintun.Adapter
	session   ssh.Session
	sshConn   ssh.Conn
	closed    bool
}

// TunnelConfig contains tunnel configuration
type TunnelConfig struct {
	AdapterName string
	LocalIP     string    // e.g., 10.10.11.1
	RemoteIP    string    // e.g., 10.10.11.2
	MTU         uint16
}

// NewTunnelManager creates a new tunnel manager
func NewTunnelManager() *TunnelManager {
	return &TunnelManager{
		closed: true,
	}
}

// CreateAdapter creates or opens a Wintun adapter
func (tm *TunnelManager) CreateAdapter(name string) error {
	// Open or create the Wintun adapter
	guid, err := wintun.GenerateGUID(name)
	if err != nil {
		return fmt.Errorf("failed to generate GUID: %w", err)
	}

	adapter, err := wintun.CreateAdapter(name, "WireGuard", guid)
	if err != nil {
		return fmt.Errorf("failed to create adapter: %w", err)
	}

	tm.adapter = adapter
	return nil
}

// ConfigureAdapter configures the network interface
func (tm *TunnelManager) ConfigureAdapter(config *TunnelConfig) error {
	if tm.adapter == nil {
		return fmt.Errorf("adapter not initialized")
	}

	// Set the MTU for the adapter
	if config.MTU == 0 {
		config.MTU = 1400
	}

	// Update adapter state
	luid := tm.adapter.LUID()

	// Set IP address
	// Note: This requires admin privileges and proper Windows API calls
	// For now, we'll establish the tunnel and routes will be managed separately
	// In production, use golang.zx2c4.com/wintun to configure addresses

	return nil
}

// EstablishSSHTunnel establishes an SSH connection for the tunnel
func (tm *TunnelManager) EstablishSSHTunnel(gatewayAddr string, config ssh.ClientConfig) (ssh.Client, error) {
	client, err := ssh.Dial("tcp", gatewayAddr, &config)
	if err != nil {
		return nil, fmt.Errorf("failed to connect to gateway: %w", err)
	}

	tm.sshConn = client.Conn
	tm.closed = false

	return client, nil
}

// OpenTunnelChannel opens a tun@openssh.com channel
func (tm *TunnelManager) OpenTunnelChannel(client ssh.Client) (ssh.Channel, <-chan ssh.Request, error) {
	channel, requests, err := client.OpenChannel("tun@openssh.com", []byte{})
	if err != nil {
		tm.closed = true
		return nil, nil, fmt.Errorf("failed to open tunnel channel: %w", err)
	}

	return channel, requests, nil
}

// BridgePackets bridges packets between the TUN adapter and SSH tunnel
// This is a blocking operation that should run in a goroutine
func (tm *TunnelManager) BridgePackets(adapter *wintun.Adapter, channel io.ReadWriter, done <-chan struct{}) error {
	if adapter == nil {
		return fmt.Errorf("adapter not initialized")
	}

	// Create a packet buffer
	buffers := make([][]byte, wintun.DefaultRingCapacity)
	sizes := make([]int, len(buffers))
	packets := make([][]byte, len(buffers))

	// Initialize buffers
	for i := range buffers {
		buffers[i] = make([]byte, wintun.DefaultPacketSize)
		packets[i] = buffers[i][:0]
	}

	bufs := make([]wintun.RingBuffer, len(packets))
	for i := range bufs {
		bufs[i].Packet = packets[i]
	}

	// Main packet bridging loop
	for {
		select {
		case <-done:
			return nil
		default:
		}

		// Read packets from adapter
		packets, err := adapter.ReceivePackets()
		if err != nil {
			return fmt.Errorf("failed to receive packets: %w", err)
		}

		for _, packet := range packets {
			// Send packet to SSH tunnel
			if _, err := channel.Write(packet); err != nil {
				return fmt.Errorf("failed to write to tunnel: %w", err)
			}
		}

		// Read packets from SSH tunnel
		packetBuffer := make([]byte, wintun.DefaultPacketSize)
		n, err := channel.Read(packetBuffer)
		if err != nil && err != io.EOF {
			return fmt.Errorf("failed to read from tunnel: %w", err)
		}

		if n > 0 {
			// Send packet to adapter
			packet := packetBuffer[:n]
			if err := adapter.SendPackets([][]byte{packet}); err != nil {
				return fmt.Errorf("failed to send packets: %w", err)
			}
		}
	}
}

// Close closes the tunnel connection and releases resources
func (tm *TunnelManager) Close() error {
	if tm.closed {
		return nil
	}

	tm.closed = true

	// Close SSH connection
	if tm.sshConn != nil {
		_ = tm.sshConn.Close()
	}

	// Delete or close adapter
	if tm.adapter != nil {
		// Note: adapter cleanup might require additional Windows API calls
		// The POC example shows adapter deletion via Windows netsh or API
	}

	return nil
}

// IsClosed returns whether the tunnel is closed
func (tm *TunnelManager) IsClosed() bool {
	return tm.closed
}

// GetAdapterName returns the adapter name
func (tm *TunnelManager) GetAdapterName() string {
	if tm.adapter == nil {
		return ""
	}
	return tm.adapter.Name()
}

// Helper function to get IP address from string
func ipToBytes(ip string) ([]byte, error) {
	addr := net.ParseIP(ip)
	if addr == nil {
		return nil, fmt.Errorf("invalid IP address: %s", ip)
	}

	ipv4 := addr.To4()
	if ipv4 == nil {
		return nil, fmt.Errorf("expected IPv4 address, got: %s", ip)
	}

	return ipv4, nil
}

// Helper function to calculate network mask from CIDR
func parseCIDR(cidr string) (*net.IPNet, error) {
	_, ipNet, err := net.ParseCIDR(cidr)
	if err != nil {
		return nil, fmt.Errorf("invalid CIDR: %s", cidr)
	}
	return ipNet, nil
}
